using System; using UnityEditor; using UnityEditor.SceneManagement; using UnityEngine; public static class Phase4A_UnitRootFix { public static void Run(){try{var sc=EditorSceneManager.OpenScene("Assets/Scenes/147VR_MainScene.unity"); var table=GameObject.Find("Prefab_WPBSA_12Foot_Snooker"); var env=GameObject.Find("ConcertRoom"); if(table==null||env==null)throw new Exception("table or ConcertRoom missing"); var parent=env.transform.Find("147VR_Table_Integration_UnitRoot"); if(parent==null){var go=new GameObject("147VR_Table_Integration_UnitRoot"); parent=go.transform; parent.SetParent(env.transform,false); parent.localPosition=Vector3.zero; parent.localRotation=Quaternion.identity; parent.localScale=Vector3.one*0.01f;} table.transform.SetParent(parent,false); table.transform.localPosition=Vector3.zero; table.transform.localRotation=Quaternion.identity; table.transform.localScale=Vector3.one; var visual=Find(table.transform,"Visual_Meshes_Drop_Here"); var surface=Find(table.transform,"TABLE SURFACE"); if(visual==null||surface==null)throw new Exception("visual/surface missing"); visual.localRotation=Quaternion.Euler(0,90,0); surface.localRotation=Quaternion.identity; PrefabUtility.RecordPrefabInstancePropertyModifications(table.transform); PrefabUtility.RecordPrefabInstancePropertyModifications(visual); PrefabUtility.RecordPrefabInstancePropertyModifications(surface); EditorSceneManager.SaveScene(sc); Debug.Log($"[4A UNITROOT FIX] parent={parent.name} parentWorld={parent.lossyScale} tableWorld={table.transform.lossyScale} visualRot={visual.eulerAngles} surfaceRot={surface.eulerAngles}"); EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(3);}} static Transform Find(Transform r,string n){foreach(var t in r.GetComponentsInChildren<Transform>(true))if(t.name==n)return t;return null;} }
